// Proteksi sederhana
$SECRET = "apeiron2024setup";
$submitted_secret = $_POST["secret"] ?? "";

$done = false;
$error = "";
$info = [];

if ($_SERVER["REQUEST_METHOD"] === "POST" && isset($_POST["write_config"])) {
    if ($submitted_secret !== $SECRET) {
        $error = "Kode rahasia salah!";
    } else {
        $config_content = <<<ENV
