# Database Configuration
DB_HOST=localhost
DB_NAME=u364155471_portal
DB_USER=u364155471_portalapeiron
DB_PASS=@PortalApr21
DB_CHARSET=utf8mb4

# Security Keys
API_KEY=355706461b2a103c48b83d4f57b3891a5b25cf89a26f829a3a2b9ddc6b230983
ENCRYPTION_KEY=18e97a4a8cd55dd5e63f61241ca69ea39f8fca2fa58af17aa2671ae35ce19f5c

# CORS Configuration
CORS_ALLOWED_ORIGINS=https://portal-apeiron.web.id,https://server-apeiron.web.id

# Session Configuration
SESSION_NAME=apeiron_license_admin
SESSION_TIMEOUT=3600

# Rate Limiting
RATE_LIMIT_ENABLED=true
RATE_LIMIT_REQUESTS=100
RATE_LIMIT_WINDOW=3600

# Application Settings
