# License Defaults
DEFAULT_EXPIRATION_DAYS=365
DEFAULT_ACTIVATION_LIMIT=1
ENV;

        $path = __DIR__ . "/config.env";
        $bytes = file_put_contents($path, $config_content);
        if ($bytes !== false) {
            $done = true;
        } else {
            $error = "Gagal menulis file! Cek permission folder.";
        }
    }
}

// Baca config.env saat ini
$current_env = [];
$env_path = __DIR__ . "/config.env";
if (file_exists($env_path)) {
    foreach (file($env_path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
        if (trim($line)[0] === "#" || strpos($line, "=") === false) continue;
        list($k, $v) = explode("=", $line, 2);
        $current_env[trim($k)] = trim($v);
    }
}

// Test DB connection
$db_ok = false;
$db_error = "";
try {
    $dsn = "mysql:host=localhost;dbname=u364155471_portal;charset=utf8mb4";
    $db = new PDO($dsn, "u364155471_portalapeiron", "@PortalApr21", [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
    $db_ok = true;
} catch (PDOException $e) {
    $db_error = $e->getMessage();
}

// Test DB dengan config.env saat ini
$db_env_ok = false;
$db_env_error = "";
if (!empty($current_env["DB_NAME"])) {
    try {
        $dsn2 = "mysql:host=" . ($current_env["DB_HOST"] ?? "localhost") . ";dbname=" . $current_env["DB_NAME"] . ";charset=utf8mb4";
        $db2 = new PDO($dsn2, $current_env["DB_USER"] ?? "", $current_env["DB_PASS"] ?? "", [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
        $db_env_ok = true;
    } catch (PDOException $e) {
        $db_env_error = $e->getMessage();
    }
}
